import sys

def is_palindrome(s):
    return s == s[::-1]

def main():
    import sys
    input = sys.stdin.read().splitlines()
    T = int(input[0])
    index = 1
    results = []
    for _ in range(T):
        A = input[index]
        B = input[index + 1]
        found = False
        for i in range(len(A)):
            for j in range(i + 1, len(A) + 1):
                s1 = A[i:j]
                for k in range(len(B)):
                    for l in range(k + 1, len(B) + 1):
                        s2 = B[k:l]
                        if is_palindrome(s1 + s2):
                            found = True
                            break
                    if found:
                        break
                if found:
                    break
            if found:
                break
        results.append("Yes" if found else "No")
        index += 2
    print("\n".join(results))

main()
